svg.script:

(function() {
  var root = document.getElementById('fm1p10-svg-root');
  if (!root) return;

  // Set initial state
  root.setAttribute('data-active-tab', 'gottron');
  root.setAttribute('data-active-joint', 'none');

  // Helper function to switch tabs
  function setActiveTab(tabId) {
    root.setAttribute('data-active-tab', tabId);
  }

  // Helper function to switch joints
  function setActiveJoint(jointId) {
    var current = root.getAttribute('data-active-joint');
    if (current === jointId) {
      root.setAttribute('data-active-joint', 'none');
    } else {
      root.setAttribute('data-active-joint', jointId);
    }
  }

  // Tab Buttons Click & Keyboard Listeners
  var tabGottron = document.getElementById('fm1p10-tab-gottron');
  var tabOcular = document.getElementById('fm1p10-tab-ocular');
  var tabSimulator = document.getElementById('fm1p10-tab-simulator');

  if (tabGottron) {
    tabGottron.addEventListener('click', function() { setActiveTab('gottron'); });
    tabGottron.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveTab('gottron'); e.preventDefault(); } });
  }
  if (tabOcular) {
    tabOcular.addEventListener('click', function() { setActiveTab('ocular'); });
    tabOcular.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveTab('ocular'); e.preventDefault(); } });
  }
  if (tabSimulator) {
    tabSimulator.addEventListener('click', function() { setActiveTab('simulator'); });
    tabSimulator.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveTab('simulator'); e.preventDefault(); } });
  }

  // Hotspot Joint Listeners
  var hsMcp = document.getElementById('fm1p10-hs-mcp');
  var hsPip = document.getElementById('fm1p10-hs-pip');
  var hsDip = document.getElementById('fm1p10-hs-dip');

  if (hsMcp) {
    hsMcp.addEventListener('click', function() { setActiveJoint('mcp'); });
    hsMcp.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveJoint('mcp'); e.preventDefault(); } });
  }
  if (hsPip) {
    hsPip.addEventListener('click', function() { setActiveJoint('pip'); });
    hsPip.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveJoint('pip'); e.preventDefault(); } });
  }
  if (hsDip) {
    hsDip.addEventListener('click', function() { setActiveJoint('dip'); });
    hsDip.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setActiveJoint('dip'); e.preventDefault(); } });
  }
})();
